import afaudit.postmortem as p
for sym in ['build_postmortem','write_postmortem','should_dump','_build_task_summary','_build_blocked_tasks','_build_session_history']:
    assert callable(getattr(p, sym)), f'{sym} is not callable'

from afaudit.postmortem import PostmortemInput
from agentfox.engine.state import ExecutionState
import typing
if hasattr(typing, 'runtime_checkable'):
    assert runtime_protocol_check(ExecutionState, PostmortemInput)
else:
    hints = typing.get_type_hints(PostmortemInput)
    for attr in hints:
        assert hasattr(ExecutionState, attr) or attr_in_init(ExecutionState, attr)

try:
    from agentfox.core.node_id import AUDIT_DIR
    assert False, 'Expected ImportError or AttributeError'
except (ImportError, AttributeError):
    pass  # expected

old_paths = ['agentfox.knowledge.audit','agentfox.knowledge.sink','agentfox.knowledge.agent_trace','agentfox.workspace.audit_cleanup']
for path in ['agentfox/','af/','nightshift/']:
    for py_file in glob_py_files(path):
        content = read_file(py_file)
        for old_path in old_paths:
            assert old_path not in content, f'{old_path} still referenced in {py_file}'

for pkg in ['agentspec','spec']:
    for py_file in glob_py_files(f'{pkg}/'):
        content = read_file(py_file)
        assert 'afaudit' not in content
        assert 'agentfox.knowledge.audit' not in content
        assert 'agentfox.knowledge.sink' not in content

module_logger_map = {'events.py':'afaudit.events','sink.py':'afaudit.sink','trace.py':'afaudit.trace','postmortem.py':'afaudit.postmortem','cleanup.py':'afaudit.cleanup','emit.py':'afaudit.emit'}
for filename, logger_name in module_logger_map.items():
    source = read_file(f'packages/afaudit/afaudit/{filename}')
    assert f"'{logger_name}'" in source or f'"{logger_name}"' in source, f'Wrong logger name in {filename}'

